# Recursive, O(n) time, O(n) call stack

def findKthBit(n: int, k: int) -> str:
    if n == 1:
        return '0'
    mid = 2 ** (n - 1)
    if k == mid:
        return '1'
    elif k < mid:
        return findKthBit(n - 1, k)
    else:
        mirrored = mid - (k - mid)
        # invert the bit
        return '1' if findKthBit(n - 1, mirrored) == '0' else '0'
